const fs=require('fs'),p=require('path'),b=process.argv[2],rd=n=>JSON.parse(fs.readFileSync(p.join(b,n),'utf8').replace(/^\uFEFF/,''));const inv=rd('Inventar_P01.json'),ids=new Set(inv.rows.flatMap(x=>[x.code,x.technical,'P01.'+x.technical]).filter(Boolean)); for(let i=1;i<=10;i++){let a='A'+String(i).padStart(2,'0'),d=rd(a+'_plan.json'),cc=d.controls||d.controale||d.checklists,pp=d.pipelines||d.pipelineuri||d.pipeline_catalog||d.pipeline;const unknown=new Set(),prev=new Set(),old=JSON.stringify(d).includes('76470fed'),unassigned=[],noEvidence=[],now=new Set();let controlOut={};for(const c of cc){let cid=c.control_id||c.id;let z=(c.task_ids||c.task_candidates||c.actual_task_candidates||[]);if(z.length===0)unassigned.push(cid);for(const id of z){if(typeof id!=='string')continue;if(!ids.has(id))unknown.add(id);else now.add(id)}let ev=c.evidence||c.evidence_by_layer||c.evidence_required||c.proof||c.probe_layers||c.probe||c.db_proof||c.backend||c.front_end||c.probe_BE;if(!ev?.length&&(!ev||Object.keys(ev).length===0))noEvidence.push(cid)}
console.log(a,'unassigned',unassigned.length,'unrecognized current',JSON.stringify([...unknown]),'recognized',now.size,'no structured evidence in representative fields',noEvidence.length,'prev SHA ref',old);}
